// Every storyline of a frozen game, told top to bottom.
//
// Generated by hoc/export/replay_js.py. Built here, in the browser, from the
// same beat data the Replay reads, by the same story layer (./story/): the
// game is replayed as dispatches and its storylines listed by type. Nothing
// about storylines is computed in Python.

import { Story } from './story/dispatch.js';
import { STORYLINE_TYPES } from './story/storylines.js';
import { houseStyle } from './story/text.js';
import { escapeHtml, storylineHtml } from './story/view.js';

const HEADINGS = {
  rivalry: 'Rivalries', union: 'Unions', succession: 'Succession questions',
  rise: 'Rises', decline: 'Declines', frontier: 'Frontiers',
};

const el = (id) => document.getElementById(id);

async function fetchJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url}: HTTP ${response.status}`);
  return response.json();
}

async function boot() {
  let index;
  let weights;
  let chunks;
  try {
    [index, weights] = await Promise.all([
      fetchJson('data/beats/index.json'),
      fetchJson('story/weights.json'),
    ]);
    chunks = await Promise.all(index.chunks.map((c) => fetchJson(`data/beats/${c.file}`)));
  } catch (error) {
    el('lines-load').textContent = `The storylines could not be loaded (${error.message}).`;
    return;
  }
  const byTurn = {};
  for (const chunk of chunks) Object.assign(byTurn, chunk.turns);
  const styles = {};
  for (const [house, info] of Object.entries(index.houses)) styles[house] = houseStyle({ house, ...info });
  const unit = index.unit === 'turn' ? 'turn' : 'season';
  const story = new Story({
    weights, baseline: index.baseline, unit,
    styleOf: (house) => styles[house] || null, ridings: index.ridings || {},
  });
  for (let turn = 1; turn <= index.turns; turn += 1) story.step(turn, byTurn[String(turn)] || []);

  const all = story.lines.all;
  const sections = [];
  const contents = [];
  for (const type of STORYLINE_TYPES) {
    const lines = all.filter((s) => s.type === type).sort((a, b) => a.opened - b.opened || (a.id < b.id ? -1 : 1));
    if (!lines.length) continue;
    contents.push(`<a href="#type-${type}">${HEADINGS[type]} (${lines.length})</a>`);
    const items = lines.map((s) => {
      const told = story.tell(s.id);
      const end = s.state === 'closed' ? `${unit}s ${s.opened}–${s.closed}` : `since ${unit} ${s.opened}`;
      return `<details class="storyline" id="${escapeHtml(s.id)}"><summary>`
        + `<span class="storyline-title">${escapeHtml(told.name)}</span>`
        + `<span class="meta"> ${told.beats.length} beat${told.beats.length === 1 ? '' : 's'} &middot; ${end}`
        + ` &middot; ${escapeHtml(s.state === 'closed' ? s.outcome : s.state)}</span></summary>`
        + storylineHtml(told, { unit, link: (turn) => `replay.html#${unit}-${turn}` })
        + '</details>';
    });
    sections.push(`<section id="type-${type}" class="storyline-type"><h2>${HEADINGS[type]}`
      + ` <span class="count">${lines.length}</span></h2>${items.join('')}</section>`);
  }
  const closed = all.filter((s) => s.state === 'closed').length;
  el('lines-summary').textContent = `${all.length} storylines over ${index.turns} ${unit}s:`
    + ` ${closed} closed, ${all.length - closed} still open when the record ends.`;
  el('lines-types').innerHTML = contents.join(' &middot; ');
  el('lines-body').innerHTML = sections.join('') || '<p class="meta">This game has no storylines.</p>';
  el('lines-load').hidden = true;
  el('lines-app').hidden = false;
  if (window.location.hash) {
    const target = document.getElementById(window.location.hash.slice(1));
    if (target && target.tagName === 'DETAILS') target.open = true;
    if (target) target.scrollIntoView();
  }
}

boot();
